package com.lbos.commercecustomer.controller; import com.lbos.commercecustomer.dto.request.*;import com.lbos.commercecustomer.dto.response.*;import com.lbos.commercecustomer.service.*;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.time.OffsetDateTime;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/retailers/me/inventory") public class InventoryController {private final InventoryService service;public InventoryController(InventoryService s){service=s;}private <T> ApiResponse<T> ok(HttpServletRequest r,String m,T d){return ApiResponse.of(Optional.ofNullable(r.getHeader("X-Correlation-Id")).orElse("not-provided"),m,d);}@GetMapping public ApiResponse<PageResponse<ProductResponse>> search(@RequestParam(required=false) String q,@RequestParam(required=false) Long categoryId,@RequestParam(required=false) String inventoryStatus,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,HttpServletRequest h){return ok(h,"Inventory retrieved",service.search(q,categoryId,inventoryStatus,page,size));}@GetMapping("/summary") public ApiResponse<InventorySummaryResponse> summary(HttpServletRequest h){return ok(h,"Inventory summary retrieved",service.summary());}@PostMapping("/adjustments") public ApiResponse<StockAdjustmentResponse> adjust(@Valid @RequestBody StockAdjustmentRequest r,HttpServletRequest h){return ok(h,"Stock adjusted",service.adjust(r));}}